		e.other:Faction(291,1,0); -- Faction: Merchants of Qeynos
		e.other:Faction(262,1,0); -- Faction: Guards of Qeynos
		e.other:AddEXP(100);
	end
	item_lib.return_items(e.self, e.other, e.trade)
